import{_ as a,o as t,c as n,ag as i}from"./chunks/framework.CxkNbRKf.js";const o="/nada-documentation/images/image83.png",r="/nada-documentation/images/image84.png",s="/nada-documentation/images/image85.png",d="/nada-documentation/images/image86.png",h="/nada-documentation/images/image87.png",g="/nada-documentation/images/image88.png",p="/nada-documentation/images/image89.png",m="/nada-documentation/images/image90.png",c="/nada-documentation/images/image91.png",q=JSON.parse('{"title":"Menu","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/site-menus.md","filePath":"admin-guide/web-ui/site-menus.md","lastUpdated":1786379412000}'),l={name:"admin-guide/web-ui/site-menus.md"};function u(w,e,b,f,_,A){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="menu" tabindex="-1">Menu <a class="header-anchor" href="#menu" aria-label="Permalink to &quot;Menu&quot;">​</a></h1><h2 id="adding-a-new-page" tabindex="-1">Adding a new page <a class="header-anchor" href="#adding-a-new-page" aria-label="Permalink to &quot;Adding a new page&quot;">​</a></h2><p>New HTML pages can be added to your NADA catalog, accessible from the main (top) menu. By default, NADA will have the Home, Catalog, Citations, and Login menu items. In the example below, the &quot;How to? item was added as a custom menu item and catalog page.</p><p><img src="'+o+'" alt=""></p><h2 id="using-the-administrator-interface" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p>Login as administrator, then click <strong>Meny &gt; All pages.</strong></p><p><img src="'+r+'" alt=""> A list of currently existing pages will be displayed. From this table, pages can be deleted, or opened to be edited. The type &quot;Link&quot; indicates that the page corresponds to NADA-generated content (default pages), not to user-designed HTML pages.</p><p><img src="'+s+'" alt=""></p><p>To add a new HTML page and create a menu item to access it, click <strong>Add new page</strong></p><p><img src="'+d+'" alt=""></p><p>Give a title to the new page, and a URL (the URL you provide here will be automatically preceded with your catalog URL). Enter the content in the HTML editor (assuming the option to edit HTML pages was activated in the catalog Settings). Indicate whether clicking on the page&#39;s menu item should open the page in the same or in a new window, and whether you want the page to be published or not (in which case it will be considered as a draft). The Weight argument is used to order the page in the menu item (which can also be done using the <strong>Reorder menu</strong> tool; see below). When done, click on <strong>Update</strong>.</p><p><img src="'+h+'" alt=""></p><p>The NADA administrator interface and the embedded HTML editor provide limited options to customize the design of the page. To produce pages with more complex content and/or design, you can use your own tools to customize this page. [where to find it? What happens when you upgrade to a new NADA?]</p><h2 id="using-the-api" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><h2 id="adding-a-new-link" tabindex="-1">Adding a new link <a class="header-anchor" href="#adding-a-new-link" aria-label="Permalink to &quot;Adding a new link&quot;">​</a></h2><p>What are links?</p><h2 id="using-the-administrator-interface-1" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface-1" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p>To add a link, proceed as for adding a new page, but click on <strong>Add new link</strong>.</p><p><img src="'+g+'" alt=""></p><p><img src="'+p+'" alt=""></p><h2 id="using-the-api-1" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api-1" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>Not doable via API.</p><h2 id="reordering-the-top-menu" tabindex="-1">Reordering the top menu <a class="header-anchor" href="#reordering-the-top-menu" aria-label="Permalink to &quot;Reordering the top menu&quot;">​</a></h2><h2 id="using-the-administrator-interface-2" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface-2" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p>To change the order in which the menu items appear in the user interface, proceed as for adding new menu, then click on <strong>Reorder menu</strong>.</p><p><img src="'+m+'" alt=""></p><p>Drag and drop to position the menu items in the desired order, then click <strong>Update</strong>.</p><p><img src="'+c+'" alt=""></p><h2 id="using-the-api-2" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api-2" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2><p>The main menu cannot be controlled by API.</p>',30)])])}const P=a(l,[["render",u]]);export{q as __pageData,P as default};
